{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C06", "C51", "C46", "C53", "C43", "C58", "C60", "C54", "C55"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C06", "C51", "C46", "C53", "C43", "C58", "C60", "C54", "C55"],
  "claims": [
    {
      "claim": "Codeine, a morphinan opioid closely related to hydromorphone, had 80.5% absolute oral bioavailability in healthy subjects after oral and IV administration, directly supporting F ≥ 20% for this scaffold.",
      "card_ids": ["C06"]
    },
    {
      "claim": "L4 records show codeine is >90% absorbed (Fa 95%) and dextromethorphan, another morphinan, is completely absorbed after oral administration, supporting high intestinal absorption for the morphinan class.",
      "card_ids": ["C51", "C46", "C53", "C43"]
    },
    {
      "claim": "L5 records show morphine is rapidly absorbed from the small intestine and transported across Caco-2 monolayers at rates well above mannitol and PEG4000, with literature bioavailability reported as 80%, supporting absorption of the 3-hydroxy morphinan core.",
      "card_ids": ["C58", "C60"]
    },
    {
      "claim": "L5 also shows rigid basic alkaloids (-)-SPD and GA2-50 have high passive permeability (Papp 40.8 × 10^-6 cm/s and > propranolol), consistent with good absorption for this compound class.",
      "card_ids": ["C54", "C55"]
    },
    {
      "claim": "L6 hepatic-clearance records are for morphine, dextromethorphan, estrone, and dimemorfan, not hydromorphone; they show first-pass metabolism in related morphinans but do not establish an extraction ratio or F < 20% for hydromorphone.",
      "card_ids": ["C66", "C68", "C70", "C72", "C73", "C74", "C77"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is supplied; prediction relies on codeine and morphine analogue evidence.",
    "L6 hepatic-clearance records are for morphine, dextromethorphan, estrone, and dimemorfan, not hydromorphone; no hydromorphone-specific CLint or extraction ratio is provided.",
    "First-pass glucuronidation and systemic clearance of hydromorphone are not directly quantified in supplied records.",
    "Low neutral fraction (0.1) at pH 7.4 is a potential absorption limitation but is not affirmative evidence of F < 20%.",
    "Most L6 records (estrone, dimemorfan, sheep/rat assays) are not directly transferable to human hydromorphone oral bioavailability."
  ],
  "decision_summary": "L6 hepatic-clearance records show first-pass metabolism in related morphinans but do not provide hydromorphone-specific extraction or F < 20% evidence. Codeine absolute F 80.5%, high Fa for codeine/dextromethorphan, and morphine/alkaloid absorption support F ≥ 20%; prediction remains high."
}

